for(const [k,[hash,kind,speech,speaker]] of Object.entries(ADV6_CUTS))
 mobileShotSpecs[k]={hash,kind,speech,speaker};

// Retain mobile-reader's grapheme-aware line breaks and source-row cursor;
// condense only the authored opening performance, independent of menu visibility.
paginate=function(rows){
 const m=mobileMetrics();let projected=rows;
 const isOpening=phase==='scene'&&state.current==='ENTRY_WAKE'&&
  rows.length>=25&&rows[0]?.id==='ENTRY_WAKE.intro.001';
 if(isOpening){
  const accepted=[];
  for(const row of rows){
   if(!ADV6_OPENING.includes(row.id))continue;
   if(row.id==='ENTRY_WAKE.intro.015'){
    accepted.push({...row,id:row.id+'.l'},{...row,id:row.id+'.g'});
   }else accepted.push(row);
  }
  projected=accepted;
 }
 const signature=projected.map(b=>[b.id,b.speaker,b.text,b.textHash].join(String.fromCharCode(0))).join(String.fromCharCode(1));
 if(mobilePageCache?.signature===signature&&mobilePageCache.key===m.key)return mobilePageCache.pages;
 const pages=projected.flatMap((row,i)=>mobileSplit(row,m,i).map(fragment=>[fragment]));
 if(!pages.length)pages.push([{speaker:'U',text:'',_row:0,_sourceId:'empty',_start:0,_end:0}]);
 mobilePageCache={signature,key:m.key,pages};return pages;
};

const ADV6_ACTION_LABELS=Object.freeze({
 ENTRY_WAKE:{canon:'先按流程，确认交接记录',rescue:'我去拿原版盘，让她唱回来',investigate:'先保住错版和切换的证据'},
 COLD:{t:'请映雪确认这一版',s:'请清辞安排切换',l:'让见月记录切换过程',g:'请晚棠核对授权',self:'我找盘，阿衡来切换'}
});
function adv6Controls(cp){
 const host=document.createElement('div');host.innerHTML=mobileButtons(cp);
 host.querySelectorAll('[data-choice]').forEach(button=>{
  const original=button.dataset.canonicalLabel||button.getAttribute('aria-label')||button.innerText||'';
  const override=ADV6_ACTION_LABELS[sourceScene().id]?.[button.dataset.choice];
  if(override){button.textContent=override;button.setAttribute('aria-label',override);}
  else if(button.classList.contains('meet-card')){
   button.textContent=original.replace('今晚找','去见').split('：')[0];
  }
  button.classList.remove('meet-card','rescue-option','first-fork-choice');
  button.classList.add('adv6-action');
 });
 host.querySelectorAll('.option-number,.meet-portrait,.meet-copy,.vn-choice-question,.first-fork-disclaimer').forEach(e=>e.remove());
 host.querySelectorAll('[data-choice-group]').forEach(button=>{
  button.querySelector('small')?.remove();button.querySelector('i')?.remove();
 });
 host.querySelectorAll('details').forEach(e=>e.remove());
 return host.innerHTML;
}
function adv6MediaForBeat(b,scene,decision){
 if(decision&&sourceScene().id==='ENTRY_WAKE')return {key:'stage',url:SCENERY};
 if(b._shot==='stage-wide')return {key:'stage',url:SCENERY};
 const key=ADV6_SCENES[b._shot];
 if(key)return {key,url:ADV6_MEDIA[key]||('assets/v6-preview/'+ADV6_MEDIA_FILES[key])};
 const speakerShots={T:'singer',L:'lin',G:'gu'};
 const voice=speakerShots[b.speaker];
 if(voice)return {key:voice,url:ADV6_MEDIA[voice]||('assets/v6-preview/'+ADV6_MEDIA_FILES[voice])};
 // One established CG per scene, not two unrelated images blended together.
 const bg=scene.background||'';
 if(['stage','theatre'].includes(bg))return {key:'piano',url:ADV6_MEDIA.piano||('assets/v6-preview/'+ADV6_MEDIA_FILES.piano)};
 return {key:'fallback',url:SCENERY};
}
function adv6Speaker(b){
 if(b.speaker==='B')return '许照 · 心声';
 if(b.speaker==='P')return '许照';
 if(b.speaker==='N'||b.speaker==='U')return '';
 if(sourceScene().id==='ENTRY_WAKE'){
  if(b.speaker==='A')return '戴耳机的工作人员';
  if(b.speaker==='T')return '台上女孩 · 话筒';
  if(b.speaker==='LU')return '琴台方向的男声';
 }
 return names[b.speaker]||mobileVoice(b);
}
/* Compact subtitles preserve the scene without forcing one short sentence into
 * a 1/4-screen blank reading slab. Respect the canonical measured paginator. */
function adv6DialogueHeight(m,text){
 mobileMeasure.textContent=text||' ';
 const measured=mobileMeasure.getBoundingClientRect().height;
 const lines=Math.max(1,Math.min(3,Math.ceil((measured-.1)/m.line)));
 const chrome=27+42+11+3+m.safe+5;
 const needed=Math.ceil(chrome+lines*m.line);
 const minimum=Math.round(m.h*(m.font>18?.225:.19));
 return Math.min(m.height,Math.max(needed,minimum));
}
function adv6Chapter(id){return {ENTRY_WAKE:'第一夜 · 侧幕',A1b:'第一夜  ·  交接',A6a:'第七天  ·  真相'}[id]||'';}
storyHTML=function(){
 const cp=currentPage(),b=cp.rows[0],m=mobileMetrics(),s=sourceScene(),scene=s.scene||{};
 const decision=cp.last&&!cp.view.isReply&&!cp.view.terminal&&cp.view.choices?.some(o=>o.enabled);
 const mode=cp.view.terminal?'ending':decision?'decision':phase==='reply'?'reply':'reading';
 const media=adv6MediaForBeat(b,scene,decision);
 const voice=adv6Speaker(b),text=b.text||'',showText=!!text&&!decision;
 const panelHeight=decision?0:adv6DialogueHeight(m,text);
 const css='--mobile-panel:'+panelHeight+'px;--mobile-font:'+m.font+'px;--mobile-line:'+m.line+'px;--mobile-safe:'+m.safe+'px;--mobile-vh:'+m.h+'px';
 const isHeroOpening=phase==='scene'&&s.id==='ENTRY_WAKE';
 const chapter=(page===0&&phase==='scene')?adv6Chapter(s.id):'';
 const optionsHTML=adv6Controls(cp);
 const dock=decision||cp.view.terminal?'<div class="vn-dock mobile-options adv6-options" role="group" aria-label="选择接下来的行动">'+optionsHTML+'</div>':'';
 const footer=decision||cp.view.terminal?'':optionsHTML;
 const inspect=isHeroOpening&&b._shot==='badge'&&media.key==='badge';
 const visual= '<div class="adv6-image" data-visual-key="'+esc(media.key)+'"><img class="adv6-scene-photo" src="'+media.url+'" alt="" loading="eager" draggable="false"></div>';
 const inspectButton=inspect?'<button class="adv6-inspect" data-adv6-inspect="badge" type="button" aria-label="仔细看工作牌">查看工作牌 <span aria-hidden="true">⌕</span></button>':'';
 return '<div class="vn-frame mobile-vn adv6" data-mode="'+mode+'" data-camera="'+esc(media.key)+'" data-art-tier="'+((media.key==='crew'||media.key==='badge')?'cg-candidate':'preview-legacy')+'" data-beat-kind="'+(b._thought?'thought':b.speaker==='N'?'narration':'dialogue')+'" data-source="'+esc(b._sourceId)+'" data-reader-key="'+esc(cp.view.id+':'+page)+'" style="'+css+'">'+
 '<section class="vn-stage mobile-stage adv6-stage" aria-label="剧情舞台">'+visual+'<div class="adv6-media-error" role="status">剧情图片暂时无法加载，请返回后重试。</div>'+'<div class="adv6-vignette" aria-hidden="true"></div>'+ (chapter?'<div class="adv6-chapter">'+esc(chapter)+'</div>':'')+inspectButton+'</section>'+dock+
 (decision?'<section class="vn-sheet mobile-sheet adv6-sheet adv6-sheet-hidden" aria-hidden="true"><div class="mobile-speaker"></div><div class="vn-scroll mobile-text"></div></section>':'<section class="vn-sheet mobile-sheet adv6-sheet" aria-label="当前对白"><div class="mobile-speaker adv6-speaker">'+esc(voice)+'</div><div class="vn-scroll mobile-text adv6-text" aria-live="polite" aria-atomic="true">'+
 (showText?'<div class="line" data-speaker="'+esc(b.speaker)+'" data-beat="'+esc(b._sourceId)+'"><p>'+esc(text)+'</p></div>':'')+'</div><div class="vn-dock mobile-dock adv6-dock">'+footer+'</div></section>')+
 '</div>';
};
// Real image inspection, not a fake ID card drawn with CSS. Capture and close
// must never issue canonical choices or move the reader cursor.
let adv6InspectOpen=false;
let adv6InspectReturnFocus=null;
function adv6CloseInspect(){document.querySelector('.adv6-modal')?.remove();adv6InspectOpen=false;if(adv6InspectReturnFocus?.isConnected)adv6InspectReturnFocus.focus();adv6InspectReturnFocus=null;}
document.addEventListener('click',event=>{
 const open=event.target.closest?.('[data-adv6-inspect]');
 const close=event.target.closest?.('[data-adv6-close]');
 if(!open&&!close)return;
 event.preventDefault();event.stopImmediatePropagation();
 if(close){adv6CloseInspect();return;}
 adv6CloseInspect();adv6InspectReturnFocus=open;adv6InspectOpen=true;
 const url=ADV6_MEDIA.badge||('assets/v6-preview/'+ADV6_MEDIA_FILES.badge);
 const box=document.createElement('div');box.className='adv6-modal';
 box.innerHTML='<div class="adv6-modal-shade" data-adv6-close="1"></div><section class="adv6-modal-frame" role="dialog" aria-modal="true" aria-label="手中的工作牌"><img src="'+url+'" alt="许照的临时场务工作牌"><p>许照 · 临时场务<br>……这是我现在的名字？</p><button type="button" class="cinema-close adv6-close" data-adv6-close="1" aria-label="关闭工作牌特写">×</button></section>';
 document.body.append(box);box.querySelector('.adv6-close')?.focus();
},true);
document.addEventListener('keydown',event=>{
 if(!adv6InspectOpen)return;
 if(event.key==='Escape'){
  event.preventDefault();event.stopImmediatePropagation();adv6CloseInspect();
 }else if(event.key==='Tab'){
  event.preventDefault();event.stopImmediatePropagation();document.querySelector('.adv6-close')?.focus();
 }
},true);
// Never substitute unrelated artwork if the intended frame cannot load.
document.addEventListener('error',event=>{
 const img=event.target;
 if(!img?.matches?.('.adv6-scene-photo'))return;
 const frame=img.closest('.adv6');if(frame)frame.dataset.mediaState='failed';
},true);
// Native source pixel density is reported to QA, never replaced with fake sharpening.
document.addEventListener('load',event=>{
 const img=event.target;
 if(!img?.matches?.('.adv6-scene-photo'))return;
 const frame=img.closest('.adv6');if(!frame)return;
 frame.dataset.mediaState='ready';
 const display=img.getBoundingClientRect(),dpr=Math.max(1,window.devicePixelRatio||1);
 const scale=Math.max(display.width/img.naturalWidth,display.height/img.naturalHeight);
 frame.dataset.mediaDensity=(1/scale>=dpr?'full':'below-device-density');
},true);

/* First-night playable director pass. Canonical engine commands remain the source of truth.
 * UI-only microchoices persist in the existing save but never masquerade as story commands.
 * This layer is mounted only at the untouched ENTRY_WAKE scene; all other scenes use the engine.
 */
const IO_VERSION = 1;
const IO_STEPS = new Set(['wake','answer','badge','badge-read','alarm','crisis','ask','ask-answer','hunt','find','confront','confront-answer','bond','final']);
function ioNew(){return {v:IO_VERSION,step:'wake',tone:'',ally:'',defiance:'',seen:[],lastFind:'',visits:0,finished:false};}
let io = ioNew();
const ioOldSnapshot=snapshot, ioOldReadPayload=readPayload, ioOldInstall=install, ioOldReset=reset, ioOldStoryHTML=storyHTML;
const ioSafe=(x,possible)=>possible.includes(x)?x:'';
function ioRead(v){
 if(!v || v.v!==IO_VERSION || !IO_STEPS.has(v.step))return ioNew();
 const seen=Array.isArray(v.seen)?[...new Set(v.seen.filter(x=>['usb','sheet','board'].includes(x)))].slice(0,3):[];
 return {v:IO_VERSION,step:v.step,tone:ioSafe(v.tone,['help','steady','confused']),ally:ioSafe(v.ally,['shen','tang','solo']),defiance:ioSafe(v.defiance,['ask','hide','stand']),seen,lastFind:ioSafe(v.lastFind,['usb','sheet','board']),visits:Math.min(40,Math.max(0,Number(v.visits)||0)),finished:!!v.finished};
}
function ioActive(){return new URLSearchParams(location.search).get('qa')!=='canonical' && panel==='story' && phase==='scene' && state.current==='ENTRY_WAKE' && !io.finished && state.history.length===0;}
snapshot=function(){const save=ioOldSnapshot();save.ui.firstNight={...io,seen:[...io.seen]};return save;};
readPayload=function(raw){const result=ioOldReadPayload(raw);result.firstNight=ioRead(raw?.ui?.firstNight);if(!raw?.ui?.firstNight&&raw?.ui?.page>0)result.firstNight.finished=true;return result;};
install=function(result){ioOldInstall(result);io=result.firstNight||ioNew();if(state.current!=='ENTRY_WAKE'||state.history.length)io.finished=true;};
reset=function(){const before=state;ioOldReset();if(state!==before && state.current==='ENTRY_WAKE' && state.history.length===0){io=ioNew();save();render();}};
function ioLine(){
 const find=io.lastFind;
 switch(io.step){
 case 'wake': return {voice:'戴耳机的工作人员',portrait:null,mood:'wake',text:'许照！站得起来吗？她的伴奏出问题了！'};
 case 'answer': return {voice:'戴耳机的工作人员',portrait:null,mood:'wake',text:io.tone==='help'?'小心脚下的线。来，抓住我。':io.tone==='steady'?'没事就快起来，舞台那边等急了。':'许照啊！你的工牌不就挂着吗？'};
 case 'badge': return {voice:'许照 · 心声',portrait:null,mood:'badge',text:'工牌？我什么时候成了这里的场务？'};
 case 'badge-read': return {voice:'许照 · 心声',portrait:null,mood:'badge',text:'许照……那个七天后会替人背锅的小说角色？'};
 case 'alarm': return {voice:'唐映雪',portrait:'t',mood:'stage',text:'别关我的麦。伴奏错了，我还能唱。'};
 case 'crisis': return {voice:'沈清辞 · 对讲机',portrait:null,mood:'stage',text:'伴奏被换了。先找到原版，我去稳住台上。'};
 case 'ask': return {voice:'唐映雪',portrait:'t',mood:'stage',text:'侧幕那边的人，是你吗？看着我，给我一个信号。'};
 case 'ask-answer': return {
   voice:io.ally==='tang'?'唐映雪':io.ally==='shen'?'沈清辞 · 对讲机':'许照 · 心声',portrait:io.ally==='tang'?'t':null,mood:'stage',
   text:io.ally==='tang'?'我听你的信号。哪怕只有四小节，我也能接住。':io.ally==='shen'?'我替你拖住现场。原版盘交给音控确认。':'先找到原版，也许还能查清是谁换的。'};
 case 'hunt': return {voice:'许照 · 心声',portrait:null,mood:'search',text:io.seen.includes('usb')?'蓝标盘找到了。该去处理台上的事了。':'控台、交接单、接线板……先查哪儿？'};
 case 'find': return {voice:'许照 · 心声',portrait:null,mood:'search',text:find==='usb'?'接线板下面……蓝胶带！原版盘就在这儿。':find==='sheet'?'交接单上写着我的名字，但我还没签。':'控台文件名和排练单上的，根本不是同一版。'};
 case 'confront': return {voice:'程放 · 身后',portrait:null,mood:'block',text:'许照，别乱碰设备。先把交接单签了。'};
 case 'confront-answer': return {voice:'程放 · 身后',portrait:null,mood:'block',text:io.defiance==='ask'?'问那么多干什么？责任人写你就行。':io.defiance==='hide'?'还不签？出了事你一个人担得起？':'沈清辞？……行，你去找她。'};
 case 'bond': return {voice:io.ally==='tang'?'唐映雪':'沈清辞 · 对讲机',portrait:io.ally==='tang'?'t':null,mood:'bond',text:io.ally==='tang'?'舞台那么亮，我还是看见你了。接下来呢？':io.ally==='shen'?'不管接下来怎么选，别替别人认错。':'映雪已经上台。现在轮到你做决定了。'};
 case 'final': return {voice:'许照 · 心声',portrait:null,mood:'decision',text:'帮她把歌唱回来，还是先保住换版证据？'};
 }
 throw Error('Unknown interactive first-night step');
}
const ioActions={
 wake:[['help','握住他的手站起来'],['steady','自己撑着设备箱起身'],['confused','“你叫我什么？”']],
 answer:[['next','继续']],
 badge:[['badge','翻开工牌']],
 'badge-read':[['next','继续']],
 alarm:[['next','继续']],crisis:[['next','继续']],
 ask:[['shen','联系沈清辞稳住舞台'],['tang','先答应唐映雪'],['solo','先查清是谁换了音乐']],
 'ask-answer':[['next','去找线索']],
 find:[['back','继续查看']],
 confront:[['ask','“为什么非要我签？”'],['hide','把发现藏好'],['stand','“我要找沈清辞确认。”']],
 'confront-answer':[['next','继续']],
 bond:[['next','面对选择']],
 final:[['rescue','把原版送上台 · 救场'],['investigate','找沈清辞核验 · 留证'],['canon','暂不碰音控 · 拒绝背锅']]
};
const ioNext={answer:'badge','badge-read':'alarm',alarm:'crisis',crisis:'ask','ask-answer':'hunt','confront-answer':'bond',bond:'final'};
function ioAction(action){
 if(!ioActive())return;
 const step=io.step;
 const allowed=step==='hunt'?['usb','sheet','board',...(io.seen.includes('usb')?['move']:[])]:ioActions[step]?.map(x=>x[0])||[];
 if(!allowed.includes(action))return;
 if(step==='wake'){io.tone=action;io.step='answer';}
 else if(step==='badge'){io.step='badge-read';}
 else if(step==='ask'){io.ally=action;io.step='ask-answer';}
 else if(step==='hunt'){
  if(action==='move'){io.step='confront';}
  else{io.lastFind=action;if(!io.seen.includes(action))io.seen.push(action);io.visits++;io.step='find';}
 }
 else if(step==='find'){io.step='hunt';}
 else if(step==='confront'){io.defiance=action;io.step='confront-answer';}
 else if(step==='final'){
  const options=renderScene(state,DATA).choices.filter(x=>x.enabled);
  if(!options.some(x=>x.id===action))throw Error('Canonical first decision not available');
  const out=choose(state,DATA,action,state.revision);
  io.finished=true;state=out.state;lastReply=out.reply;phase=lastReply.length?'reply':'scene';page=0;choicePage=0;
 } else io.step=ioNext[step]||step;
 save();render();arm();
}
function ioArt(info){
 // The only visual layer is one physically coherent event photograph.
 // Older portrait cutouts, CSS ID cards and fake prop drawings are never mounted.
 const key=info.mood==='wake'?'crew':info.mood==='badge'?'badge':
   (info.portrait==='t'&&(info.mood==='stage'||info.mood==='bond'))?'singer':'stage';
 const url=key==='stage'?SCENERY:(ADV6_MEDIA[key]||('assets/v6-preview/'+ADV6_MEDIA_FILES[key]));
 return '<div class="io-film" data-io-shot="'+esc(key)+'"><img class="io-film-image" src="'+url+'" draggable="false" loading="eager" alt="" /></div>'+
 '<div class="io-film-vignette" aria-hidden="true"></div>';
}
function ioChoices(step){
 if(step==='hunt'){
  const items=[['board','查看控台版本'],['sheet','核对交接单'],['usb','检查接线板']];
  return '<div class="io-hotspots" role="group" aria-label="亲手调查后台">'+items.map(([action,label])=>
   '<button type="button" class="io-hotspot '+(io.seen.includes(action)?'seen':'')+'" data-io="'+action+'"><span aria-hidden="true">'+(io.seen.includes(action)?'✓':'⌕')+'</span>'+esc(label)+'</button>').join('')+'</div>'+
   (io.seen.includes('usb')?'<button type="button" class="io-advance" data-io="move">去处理舞台危机 <span aria-hidden="true">›</span></button>':'');
 }
 const list=ioActions[step]||[];
 return '<div class="io-choice-stack" role="group" aria-label="选择接下来的行动">'+list.map(([id,label])=>
  '<button type="button" data-io="'+esc(id)+'" class="'+(list.length===1?'io-single':'io-choice')+'">'+esc(label)+' <span aria-hidden="true">'+(list.length===1?'›':'↗')+'</span></button>').join('')+'</div>';
}
function ioStoryHTML(){
 const info=ioLine(),m=mobileMetrics(),actionCount=(ioActions[io.step]||[]).length;
 const decision=actionCount>1||io.step==='hunt';
 const panelHeight=Math.min(220,Math.floor(m.h*(m.h<650?.30:.24)));
 const style='--mobile-panel:'+panelHeight+'px;--mobile-font:'+Math.min(20,m.font)+'px;--mobile-line:'+m.line+'px;--mobile-safe:'+m.safe+'px;--mobile-vh:'+m.h+'px';
 return '<div class="vn-frame mobile-vn io-vn" data-mode="'+(decision?'decision':'reading')+'" data-current-io="'+esc(io.step)+'" data-io-art-tier="candidate-not-approved" style="'+style+'">'+
 '<section class="vn-stage mobile-stage io-stage" aria-label="第一夜的舞台后台">'+ioArt(info)+'<div class="io-corner">第一夜 · 侧幕</div>'+
 (io.step==='hunt'?ioChoices('hunt'):'')+'</section>'+
 (io.step!=='hunt'&&decision?'<div class="io-options">'+ioChoices(io.step)+'</div>':'')+
 '<section class="vn-sheet mobile-sheet io-sheet" aria-label="当前角色的一句对白"><div class="mobile-speaker">'+esc(info.voice)+'</div>'+
 '<div class="vn-scroll mobile-text" aria-live="polite" aria-atomic="true"><div class="line"><p>'+esc(info.text)+'</p></div></div>'+
 '<div class="io-bottom">'+(!decision?ioChoices(io.step):'')+'</div></section></div>';
}
storyHTML=function(){return ioActive()?ioStoryHTML():ioOldStoryHTML();};
// The first-night menu/history must describe the actual played sequence,
// never expose the discarded 28-paragraph draft as if the player had read it.
const ioOldMenuHTML=menuHTML,ioOldHistoryHTML=historyHTML,ioOldRowsHTML=rowsHTML;
menuHTML=function(){
 const old=ioOldMenuHTML();
 if(new URLSearchParams(location.search).get('qa')!=='canonical'&&state.current==='ENTRY_WAKE'&&!io.finished)return old.replace(/<details class="panel"><summary>当前场景文字记录<\/summary>[\s\S]*?<\/details>$/,
  '<section class="panel small"><h3>这一夜</h3><p>对话、调查和已作出的行动已经自动保存。</p></section>');
 return old;
};
historyHTML=function(){
 if(new URLSearchParams(location.search).get('qa')!=='canonical'&&state.current==='ENTRY_WAKE'&&!io.finished){
  const detail=io.seen.length?'已查看：'+io.seen.map(k=>({usb:'接线板',sheet:'交接单',board:'控台'}[k])).join('、'):'还没有发现可记录的线索。';
  return '<h2>第一夜 · 我的行动</h2><section class="panel"><p>'+esc(detail)+'</p><p class="small">回到剧情继续调查。</p></section>';
 }
 return ioOldHistoryHTML();
};
rowsHTML=function(rows,id){
 if(new URLSearchParams(location.search).get('qa')!=='canonical'&&panel==='history'&&id==='ENTRY_WAKE'&&io.finished){
  const who=({shen:'沈清辞',tang:'唐映雪',solo:'自己'}[io.ally])||'现场的人';
  return '<div class="line dialogue"><p>我自己确认了工牌，检查过后台，决定先找'+esc(who)+'。之后，才做出了真正改变演出的选择。</p></div>';
 }
 return ioOldRowsHTML(rows,id);
};

// Capture before the legacy delegated controller. No fake story commands are generated.
document.addEventListener('pointerup',e=>{
 if(ioActive() && e.target instanceof Element && e.target.closest('.io-vn'))e.stopImmediatePropagation();
},true);
document.addEventListener('click',e=>{
 if(!ioActive())return;
 const element=e.target instanceof Element?e.target:null;
 const btn=element?.closest('[data-io]');
 if(!btn && element?.closest('.io-vn')){e.preventDefault();e.stopImmediatePropagation();const actions=ioActions[io.step];if(actions?.length===1&&actions[0][0]==='next')ioAction('next');return;}
 if(!btn)return;
 e.preventDefault();e.stopImmediatePropagation();
 if(btn.disabled||!btn.isConnected)return;
 try{ioAction(btn.dataset.io);}catch(err){notice='本次互动未完成：'+err.message;showNotice();}
},true);

/* First-night continuity director: after the first fork, keep subsequent early
 * consequential scenes interactive. Choices always call the canonical engine. */
const IF_FOLLOW={
 ENTRY_MEMORY:{voice:'沈清辞',portrait:'s',mood:'stage',text:'原版在手。谁能帮我们留下证据？',labels:{camera:'请林见月拍下切换记录',email:'找顾晚棠核对授权邮件'}},
 ENTRY_CLUES:{voice:'程放',portrait:null,mood:'block',text:'交接单在这儿。来，把字签了。',labels:{obey:'签字，先离开',refuse:'当面拒签',witness:'先留下时间线'}},
 COLD:{voice:'阿衡',portrait:null,mood:'stage',text:'原版别自己插。我试听，你去找人喊切换。',labels:{t:'找唐映雪',s:'找沈清辞',l:'找林见月',g:'找顾晚棠',self:'和阿衡一起处理'}},
 OP_SETTLE:{voice:'阿衡',portrait:null,mood:'block',text:'有人要删错版文件。今晚得留个证据。',labels:{backup:'暗中备份两种版本',confront:'在工作群追问删档令',quiet:'先保留交接记录'}},
 OP_FORK:{voice:'阿衡',portrait:null,mood:'block',text:'录音我留着。你想现在追问，还是先等？',labels:{backup:'暗中备份两种版本',confront:'在工作群追问删档令',quiet:'先保留交接记录'}},
 OP_CANON:{voice:'程放',portrait:null,mood:'block',text:'还不签？难道这场错版跟你没关系？',labels:{backstage:'和阿衡一起核对',question:'当面追问程放',silence:'先记住谁要我签字'}},
 OP_TALK_t:{voice:'唐映雪',portrait:'t',mood:'bond',text:'刚才灯那么亮，我还是认出你了。',labels:{flirt:'“我只是很想再听你唱。”',slow:'“还没缓过来。”',work:'“下场演出，我还能来吗？”'}},
 OP_TALK_s:{voice:'沈清辞',portrait:'s',mood:'bond',text:'喝点水。还有，你能留个号码吗？',labels:{flirt:'“不谈工作，也能找你吗？”',slow:'“我还紧张，先慢一点。”',work:'“先留工作号吧。”'}},
 OP_TALK_l:{voice:'林见月',portrait:'l',mood:'bond',text:'这么多人，只有你一直躲我的镜头。',labels:{flirt:'“下一张，换我拍你？”',slow:'“今天先不拍，好吗？”',work:'“先记下谁救了场。”'}},
 OP_TALK_g:{voice:'顾晚棠',portrait:'g',mood:'bond',text:'那个原版盘，你怎么找到的？',labels:{flirt:'“现在不谈工作，能认识你吗？”',slow:'“先让我把话说顺。”',work:'“我想再争取一次机会。”'}}
};
let ioFollowGroup='';
const ioFPrevSnapshot=snapshot,ioFPrevReadPayload=readPayload,ioFPrevInstall=install,ioFPrevReset=reset,ioFPrevStoryHTML=storyHTML;
snapshot=function(){const x=ioFPrevSnapshot();x.ui.followGroup=ioFollowGroup;return x;};
readPayload=function(raw){const x=ioFPrevReadPayload(raw);x.followGroup=['stage','records'].includes(raw?.ui?.followGroup)?raw.ui.followGroup:'';return x;};
install=function(x){ioFPrevInstall(x);ioFollowGroup=x.followGroup||'';};
reset=function(){const original=state;ioFPrevReset();if(state!==original&&state.history.length===0)ioFollowGroup='';};
function ioFollowActive(){return new URLSearchParams(location.search).get('qa')!=='canonical'&&panel==='story'&&phase==='scene'&&state.history.length>0&&Object.hasOwn(IF_FOLLOW,state.current);}
function ioFollowEnabled(){
 if(state.current==='OP_SETTLE'){
  const bridge=directBridge();
  return bridge?.next?.choices.filter(x=>x.enabled)||[];
 }
 return renderScene(state,DATA).choices.filter(x=>x.enabled);
}
function ioFollowOptions(){
 const scene=IF_FOLLOW[state.current],actions=ioFollowEnabled();
 const button=(c)=>'<button type="button" data-if-pick="'+esc(c.id)+'" class="io-choice">'+esc(scene.labels[c.id]||c.label)+' <span aria-hidden="true">↗</span></button>';
 if(state.current==='COLD'&&actions.length>3){
  if(!ioFollowGroup){
   const self=actions.find(x=>x.id==='self');
   return [['stage','先去找台上的人'],['records','先问能留证的人']].map(([id,label])=>'<button class="io-choice" type="button" data-if-group="'+id+'">'+esc(label)+' <span aria-hidden="true">↗</span></button>').join('')+(self?button(self):'');
  }
  const keys=ioFollowGroup==='stage'?['t','s']:['l','g'];
  return keys.map(id=>actions.find(x=>x.id===id)).filter(Boolean).map(button).join('')+'<button class="io-choice io-back" type="button" data-if-back="1">‹ 换一组</button>';
 }
 return actions.map(button).join('');
}
function ioFollowHTML(){
 const scene=IF_FOLLOW[state.current],m=mobileMetrics(),sheet=Math.floor(Math.min(148,m.h/4));
 const style='--mobile-panel:'+sheet+'px;--mobile-font:'+Math.min(20,m.font)+'px;--mobile-line:'+m.line+'px;--mobile-safe:'+m.safe+'px;--mobile-vh:'+m.h+'px';
 return '<div class="vn-frame mobile-vn io-vn io-follow" data-mode="decision" data-follow-scene="'+esc(state.current)+'" style="'+style+'">'+
 '<section class="vn-stage mobile-stage io-stage">'+ioArt(scene)+'<div class="io-corner">第一夜 <span>·</span> 北岸剧场</div></section>'+
 '<div class="io-options"><div class="io-choice-stack" role="group" aria-label="选择行动">'+ioFollowOptions()+'</div></div>'+
 '<section class="vn-sheet mobile-sheet io-sheet"><div class="mobile-speaker">'+esc(scene.voice)+'</div><div class="vn-scroll mobile-text"><div class="line"><p>'+esc(scene.text)+'</p></div></div><div class="io-bottom"></div></section></div>';
}
storyHTML=function(){return ioFollowActive()?ioFollowHTML():ioFPrevStoryHTML();};
function ioFollowPick(id){
 const valid=ioFollowEnabled();if(!valid.some(x=>x.id===id))return;
 if(state.current==='OP_SETTLE'){
  const first=choose(state,DATA,'continue',state.revision);
  state=first.state;
 }
 const outcome=choose(state,DATA,id,state.revision);
 state=outcome.state;lastReply=outcome.reply;
 phase=lastReply.length?'reply':'scene';page=0;choicePage=0;ioFollowGroup='';
 save();render();arm();
}
document.addEventListener('pointerup',e=>{
 if(ioFollowActive()&&e.target instanceof Element&&e.target.closest('.io-follow'))e.stopImmediatePropagation();
},true);
document.addEventListener('click',e=>{
 if(!ioFollowActive())return;
 const element=e.target instanceof Element?e.target:null;
 const target=element?.closest('[data-if-pick],[data-if-group],[data-if-back]');
 if(!target&&element?.closest('.io-follow')){e.stopImmediatePropagation();return;}
 if(!target||target.disabled||!target.isConnected)return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  if(target.dataset.ifGroup){ioFollowGroup=target.dataset.ifGroup;save();render();arm();}
  else if(target.dataset.ifBack){ioFollowGroup='';save();render();arm();}
  else ioFollowPick(target.dataset.ifPick);
 }catch(err){notice='剧情选择失败：'+err.message;showNotice();}
},true);

load();render();
